import { html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import { DsElement, define, tag } from '@/elements/lib/element'
import { html as staticHtml } from 'lit/static-html.js'
import '@/elements/components/ui/fact'
import styles from 'virtual:tw'

// Facts.vue as <conare-facts>: short facts about one thing (console2.css .v2-fact): each a small hairline box with its
// name, muted, and its value, so a row of them wraps cleanly. Pass `facts`, or write <conare-fact> inside. `mono` sets a
// value in Geist Mono (a domain, an ID). Six at most; a value that needs a sentence is not a fact.
export type FactItem = { name: string, value: string, mono?: boolean }

/**
 * @summary Short facts about one thing, each a small hairline box.
 * @slot - <conare-fact> elements, in place of `facts`.
 */
export class Facts extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { facts: { type: Array } }

	/** The facts: [{ name, value, mono? }]. */
	facts: FactItem[] = []

	render() {
		const fact = tag('fact')
		return html`<dl class="contents"><slot>${repeat(this.facts ?? [], (f) => f.name, (f) => staticHtml`<${fact} name=${f.name} value=${f.value} ?mono=${!!f.mono}></${fact}>`)}</slot></dl>`
	}
}

define('facts', Facts)

/* The host is the facts' box (Facts.vue's <dl>), so a class on <conare-facts> (justify-center) lands on it as a class on
   <Facts> does; the <dl> inside keeps the list's meaning and lays out nothing. */
:host { @apply flex flex-wrap gap-2; }

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Fact.vue as <conare-fact>: one fact, a 24px hairline box, 12px, the name muted and the value in ink. Inside
// <conare-facts>.

/**
 * @summary One fact: its name, muted, and its value.
 * @slot - The value, in place of `value`.
 */
export class Fact extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { name: {}, value: {}, mono: { type: Boolean } }

	/** The fact's name. */
	name = ''
	/** Its value. */
	value?: string
	/** The value in Geist Mono (a domain, an ID). */
	mono = false

	render() {
		return html`<div data-ds="fact" class="flex min-w-0 items-center gap-1.5 border border-edge bg-surface px-2 py-1 type-meta">
			<dt class="text-fg-muted">${this.name}</dt>
			<dd class=${['min-w-0', this.mono ? 'font-code' : ''].join(' ')}><slot>${this.value}</slot></dd>
		</div>`
	}
}

define('fact', Fact)
